--- 设置对决状态
---@param state any
function LadderStruggleRecordPlayerTeam:SetStatuUI(state)
    KTool.SetActive(self.STxt_Result.gameObject, false)
    KTool.SetActive(self.RT_SkipMask.gameObject, false)
    if state == BattleResult.Win then
        KTool.SetActive(self.STxt_Result.gameObject, true)
        self.STxt_Result.Status = 1
    elseif state == BattleResult.Lose then
        KTool.SetActive(self.STxt_Result.gameObject, true)
        self.STxt_Result.Status = 2
    elseif state == BattleResult.Skip then
        KTool.SetActive(self.RT_SkipMask.gameObject, true)
        KTool.SetActive(self.Btn_Replay.gameObject, false)
    end
end

function LadderStruggleRecordPlayerTeam:MakeTeamData(teamInfo)
    local teamData = {}
    local team = teamInfo[1]
    for i, cardInfo in ipairs(team) do
        local cardData = {
            cardId = cardInfo.cardId,
            advanceLevel = cardInfo.advanceLevel,
            star = cardInfo.star,
            cardLevel = cardInfo.level,
        }
        table.insert(teamData, cardData)
    end
    return teamData
end

