end

--- 设置单卡的存活状态
---@param data any
---@param which any
function LadderStruggleRecordPlayerTeam:SetOneCardAliveState(data, which)
    if which == 1 then
        self.LT_TeamL:FillOneCardAliveState(data)
    elseif which == 2 then
        self.LT_TeamR:FillOneCardAliveState(data)
    end
end

