--- 播放录像
function LadderStruggleRecordPlayerTeam:ReplayBattle()
    LadderStruggleMgr.isRecordReplay = true
    LadderStruggleMgr.struggleNextSessionIndex = self.sessionIndex + 1
    FightPreWarMgr:GetInstance():FightReplay(table.serialize(self.records))
end

